#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
================================================================================
  ASX EX-DIVIDEND RECOVERY PATTERN ANALYZER
================================================================================

  HOW TO RUN THIS
  ---------------
  macOS:    Open Terminal (Cmd+Space, type "Terminal"), then type  python3
            followed by a SPACE, then drag this file into the window and
            press Enter.

  Windows:  Right-click this file and choose "Open with" > "Python".
            (Or open Command Prompt and run:  python "path\to\this\file.py")

  The first run takes 1-3 minutes to set up. After that it starts in seconds.
  Your web browser opens automatically. Press Ctrl+C in the black window to stop.

  Needs Python 3.9+ and an internet connection (for share price data).
  Get Python free at https://www.python.org/downloads/  (on Windows, TICK
  "Add Python to PATH" during install).

  Historical observations only - not investment advice or future predictions.
================================================================================
"""

import base64
import hashlib
import io
import os
import platform
import shutil
import socket
import subprocess
import sys
import time
import zipfile

APP_NAME = "ASX Ex-Dividend Analyzer"
PACKAGES = ["fastapi>=0.110", "uvicorn>=0.29", "yfinance>=0.2.40",
            "pandas>=2.0", "numpy>=1.26"]
PREFERRED_PORT = 8477


def say(msg=""):
    print(msg, flush=True)


def banner():
    say("=" * 66)
    say("  " + APP_NAME.upper())
    say("=" * 66)
    say()


def die(msg, detail=""):
    say()
    say("-" * 66)
    say("  COULD NOT START")
    say("-" * 66)
    say("  " + msg)
    if detail:
        say()
        for line in str(detail).strip().splitlines()[-12:]:
            say("    " + line)
    say()
    try:
        input("  Press Enter to close this window. ")
    except Exception:
        pass
    sys.exit(1)


def check_python():
    if sys.version_info < (3, 9):
        die("This app needs Python 3.9 or newer. You have %d.%d." %
            (sys.version_info[0], sys.version_info[1]),
            "Download a newer version free from https://www.python.org/downloads/")


def app_dir():
    """A stable folder to unpack into, in the user's home directory."""
    home = os.path.expanduser("~")
    return os.path.join(home, ".asx_exdiv_analyzer")


def unpack(target):
    """Extract the embedded app files if missing or out of date."""
    raw = base64.b64decode("".join(PAYLOAD.split()))
    stamp = hashlib.sha256(raw).hexdigest()[:16]
    stamp_file = os.path.join(target, "version.txt")

    current = None
    if os.path.exists(stamp_file):
        try:
            with open(stamp_file) as fh:
                current = fh.read().strip()
        except Exception:
            current = None

    if current == stamp and os.path.exists(os.path.join(target, "backend", "main.py")):
        return  # already up to date

    say("  Unpacking application files...")
    for sub in ("backend", "frontend"):
        p = os.path.join(target, sub)
        if os.path.isdir(p):
            shutil.rmtree(p, ignore_errors=True)
    os.makedirs(target, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        zf.extractall(target)
    os.makedirs(os.path.join(target, "backend", "cache"), exist_ok=True)
    with open(stamp_file, "w") as fh:
        fh.write(stamp)


def venv_python(venv):
    if platform.system() == "Windows":
        return os.path.join(venv, "Scripts", "python.exe")
    return os.path.join(venv, "bin", "python")


def ensure_env(target):
    """Create a private virtual environment and install dependencies."""
    venv = os.path.join(target, "env")
    py = venv_python(venv)
    marker = os.path.join(venv, "installed.txt")

    if os.path.exists(py) and os.path.exists(marker):
        return py

    if not os.path.exists(py):
        say("  Setting up (first run only) - this takes 1-3 minutes...")
        say("  Creating a private Python environment...")
        try:
            subprocess.run([sys.executable, "-m", "venv", venv],
                           check=True, capture_output=True, text=True)
        except subprocess.CalledProcessError as e:
            die("Could not create the Python environment.",
                (e.stderr or "") + (e.stdout or ""))
        except FileNotFoundError:
            die("Python's venv module is unavailable on this machine.",
                "On Debian/Ubuntu Linux try: sudo apt install python3-venv")

    say("  Downloading required libraries (needs internet)...")
    try:
        subprocess.run([py, "-m", "pip", "install", "--upgrade", "pip", "--quiet"],
                       check=False, capture_output=True, text=True, timeout=600)
        res = subprocess.run([py, "-m", "pip", "install", "--quiet"] + PACKAGES,
                             check=True, capture_output=True, text=True, timeout=1800)
    except subprocess.CalledProcessError as e:
        die("Could not download the required libraries. Check your internet "
            "connection (a company firewall or VPN can block this) and try again.",
            (e.stderr or "") + (e.stdout or ""))
    except subprocess.TimeoutExpired:
        die("The library download timed out. Check your internet connection "
            "and run this file again.")

    with open(marker, "w") as fh:
        fh.write("ok\n")
    say("  Setup complete.")
    return py


def free_port(preferred):
    for port in [preferred] + list(range(preferred + 1, preferred + 25)):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            try:
                s.bind(("127.0.0.1", port))
                return port
            except OSError:
                continue
    die("No free network port available on this computer.")


def wait_until_up(port, proc, timeout=90):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if proc.poll() is not None:
            return False
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(0.7)
            if s.connect_ex(("127.0.0.1", port)) == 0:
                return True
        time.sleep(0.4)
    return False


def main():
    banner()
    check_python()

    target = app_dir()
    try:
        os.makedirs(target, exist_ok=True)
        unpack(target)
    except Exception as e:
        die("Could not unpack the application files into your home folder.", e)

    py = ensure_env(target)
    port = free_port(PREFERRED_PORT)
    url = "http://127.0.0.1:%d" % port

    say()
    say("  Starting the analyzer...")
    backend = os.path.join(target, "backend")
    env = dict(os.environ)
    env["PYTHONUNBUFFERED"] = "1"
    try:
        proc = subprocess.Popen(
            [py, "-m", "uvicorn", "main:app", "--host", "127.0.0.1",
             "--port", str(port), "--log-level", "warning"],
            cwd=backend, env=env)
    except Exception as e:
        die("The analyzer failed to start.", e)

    if not wait_until_up(port, proc):
        die("The analyzer did not start correctly. Please try running this file again.")

    say()
    say("=" * 66)
    say("  READY - your browser should open automatically.")
    say()
    say("  If it does not, open your browser and go to:")
    say("      " + url)
    say()
    say("  Start on ASX Top 20 Opportunities and press 'Run scan',")
    say("  or search a single code (BHP, CBA, WES...) on the other tab.")
    say("  'Demo scan' / code DEMO explores with sample data, no internet needed.")
    say()
    say("  Leave this window open while using the app.")
    say("  Press Ctrl+C here to stop.")
    say("=" * 66)
    say()

    try:
        import webbrowser
        webbrowser.open(url)
    except Exception:
        pass

    try:
        proc.wait()
    except KeyboardInterrupt:
        say()
        say("  Stopping...")
        try:
            proc.terminate()
            proc.wait(timeout=10)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
        say("  Stopped. You can close this window.")


